import { screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { renderWithProviders } from "../../../tests/utils";
import { CommonEventInfo } from "./CommonEventInfo";

const event = {
  timestamp: new Date().toISOString(),
  id: "event-1",
  conversationEventType: "bot",
  metadata: {
    langfuse_trace_url: "https://langfuse.test/project/p1/traces/t1",
    langfuse_trace_id: "t1",
  },
};

describe("CommonEventInfo", () => {
  it("renders the Langfuse trace link when the event carries a trace URL", () => {
    renderWithProviders(<CommonEventInfo event={event} />);

    expect(screen.getByTestId("event-trace-link")).toBeInTheDocument();
    expect(screen.getByText("Open in Langfuse")).toBeInTheDocument();
  });

  it("hides the Langfuse trace link when langfuseEnabled is false", () => {
    renderWithProviders(<CommonEventInfo event={event} />, {
      initialStoreState: { langfuseEnabled: false },
    });

    expect(screen.queryByTestId("event-trace-link")).not.toBeInTheDocument();
    expect(screen.queryByText("Open in Langfuse")).not.toBeInTheDocument();
  });

  it("still renders the remaining event fields when the link is hidden", () => {
    renderWithProviders(<CommonEventInfo event={event} />, {
      initialStoreState: { langfuseEnabled: false },
    });

    expect(screen.getByTestId("event-occurred-at")).toBeInTheDocument();
    expect(screen.getByTestId("event-type")).toBeInTheDocument();
  });
});
